record.field:
if record and record.res_model and record.res_id:
    duplicate = env['mail.activity'].search([
        ('id', '!=', record.id),
        ('res_model', '=', record.res_model),
        ('res_id', '=', record.res_id),
        ('activity_type_id', '=', record.activity_type_id.id),
    ], limit=1)

    if duplicate:
        raise UserError(
            'Source record %s (%s) đã tồn tại Activity "%s" đang active.'
            % (
                record.res_id,
                record.res_model,
                record.activity_type_id.name,
            )
        )
